var i=168;var n=`168-soup-texture-consistency-and-blending`;var s=`161`;var a={en:`Soup Texture, Consistency, and Blending`,ua:`Текстура, консистенція та подрібнення супів`};var o={short:`Soup consistency depends on the balance of liquid, starch, vegetables, fat, and air introduced during blending. Different thickening strategies produce different mouthfeel, even when the soups look equally dense.`,sections:[{title:`Core idea`,text:`A smooth purée comes from sufficiently tender ingredients and suitable blending. Cream soup may depend on dairy or a starch-thickened base; a vegetable purée can be creamy without adding cream.`},{title:`Science`,text:`Pectin and cell-wall fragments influence vegetable thickness, gelatinized starch thickens broth, and fat droplets add richness. Aggressive blending of starchy potato can release excessive starch and make the soup gluey.`},{title:`How to apply`,text:`Cook vegetables to a suitable tenderness, blend cautiously in small batches with vented equipment for hot liquids, pass through a sieve if needed, and adjust thickness with stock. Add dairy gently and check final seasoning after dilution.`},{title:`Practical experiment`,text:`Divide a cooked carrot soup into three portions: blend one without additions, one with a little cream, and one with cooked white beans. Compare mouthfeel, coating and stability after reheating safely.`},{title:`Common mistakes`,text:`Filling a sealed blender with very hot soup risks explosive splashing. Thick soup can still be bland. An excess of flour or starch creates pasty texture, while prolonged boiling can destabilize cream.`},{title:`Related theories`,text:`049, 053, 167, 169.`}]};var l={short:`Консистенція супу залежить від співвідношення рідини, крохмалю, овочів, жиру та повітря, введеного під час подрібнення. Різні способи загущення створюють різне відчуття текстури навіть за схожої густоти.`,sections:[{title:`Суть`,text:`Однорідне пюре отримують із достатньо м’яких продуктів та відповідного подрібнення. Крем-суп може містити вершки чи борошняну основу, але овочевий суп-пюре може бути ніжним і без молочних продуктів.`},{title:`Наука`,text:`Пектин і частинки клітинних стінок впливають на густоту, клейстеризований крохмаль загущує рідину, а дрібні краплі жиру надають насиченості. Надмірне подрібнення картоплі іноді звільняє забагато крохмалю й робить суп клейким.`},{title:`Як застосувати`,text:`Зваріть овочі до м’якості, обережно подрібнюйте невеликими порціями у придатному для гарячого обладнанні з відведенням пари. За потреби протріть крізь сито, відрегулюйте густоту бульйоном і делікатно додайте молочний компонент.`},{title:`Практичний дослід`,text:`Поділіть морквяний суп на три частини: одну залиште без добавок, у другу введіть вершки, у третю додайте варену білу квасолю. Порівняйте відчуття густоти та стабільність після безпечного розігрівання.`},{title:`Поширені помилки`,text:`Гарячий суп у герметично закритому блендері може небезпечно розбризкатися. Густота не замінює смаку, надлишок борошна дає пастоподібну текстуру, а довге кипіння може розшарувати вершки.`},{title:`Пов’язані теорії`,text:`049, 053, 167, 169.`}]};var r=[49,53,167,169];var d=`References / Джерела`;var c=[`https://www.theculinarypro.com/soups`,`https://www.fda.gov/food/buy-store-serve-safe-food/safe-food-handling`];var h={id:168,slug:n,group:`161`,title:a,en:o,ua:l,related:r,referenceTitle:d,references:c};export{h as default,o as en,s as group,i as id,d as referenceTitle,c as references,r as related,n as slug,a as title,l as ua};